function VideoPanel({
  title,
  src,
  strip,
  caption,
}: {
  title: string;
  src: string;
  strip: string;
  caption: string;
}) {
  return (
    <Stack gap={8}>
      <H3>{title}</H3>
      <img
        src={strip}
        alt={title}
        style={{ width: "100%", height: "auto", display: "block" }}
      />
      <Text size="small" tone="tertiary">
        Stills at 0 s, 1 s, 2 s, 4 s, 6 s. Canvas cannot play local mp4s — open
        the file in the editor.
      </Text>
      <Text>
        <Code>{src}</Code>
      </Text>
      <Link href={src}>Open this mp4 in the editor</Link>
      <Text size="small" tone="secondary">
        {caption}
      </Text>
    </Stack>
  );
}

export default function SquatMjlabVsIsaac() {
  return (
    <Stack gap={24}>
      <Stack gap={8}>
        <H1>Same squat policy: mjlab succeeds, Isaac Sim falls</H1>
        <Text tone="secondary">
          Policy `x2_squat_policy_40pct_iter16499.npz` (102-D obs, 31-DoF X2, 50 Hz,
          5.0 s stand–squat–stand then hold, wrap_cycle=False). Isaac uses the existing
          Holosoma WBT plant only as the physical robot, then drives this npz — not the
          box-pickup policy. Videos are in `Agibot-humanoid/squat/videos/`
          (open the mp4s in the editor; the canvas cannot play them).
        </Text>
      </Stack>

      <Callout tone="danger" title="Not the same output">
        Height tracks for about 0.9 s, then Isaac pitches over during descent and
        stays on the floor. mjlab reaches 0.276 m, stands back up, and stays within
        4° of upright. First height gap &gt; 2 cm at 0.88 s; Isaac pelvis is on the
        ground by 1.7 s.
      </Callout>

      <Row gap={24} wrap>
        <Stat value="success" label="mjlab 40% squat" tone="success" />
        <Stat value="fall" label="Isaac Sim (Holosoma X2)" tone="danger" />
        <Stat value="0.88 s" label="First height gap > 2 cm" tone="warning" />
        <Stat value="0.42 m" label="Pelvis height RMSE" />
      </Row>

      <Divider />

      <Stack gap={10}>
        <H2>Rollouts</H2>
        <Grid columns={2} gap={20}>
          <VideoPanel
            title="mjlab (native renderer)"
            src={MJLAB_MP4}
            strip={MJLAB_STRIP}
            caption="Physics + RGB from mjlab. Stands, squats to 40% (0.276 m), stands again."
          />
          <VideoPanel
            title="Isaac Sim states (replayed in mjlab viewer)"
            src={ISAAC_MP4}
            strip={ISAAC_STRIP}
            caption="Kit RTX cameras cannot run headless here. This is the Isaac pelvis/joint trajectory, kinematically replayed. Descent collapses around 1.6 s."
          />
        </Grid>
      </Stack>

      <Stack gap={8}>
        <H2>Pelvis height</H2>
        <Text size="small" tone="secondary">
          Origin-corrected pelvis z. Dashed lines: standing 0.69 m and 40% target
          0.276 m. Sampled every 0.1 s.
        </Text>
        <LineChart
          categories={T}
          series={[
            { name: "mjlab", data: H_MJ, tone: "success" },
            { name: "Isaac Sim", data: H_IS, tone: "danger" },
          ]}
          height={280}
          yMin={0}
          yMax={0.75}
          fill
          referenceLines={[
            { value: 0.69, label: "stand 0.69 m" },
            { value: 0.276, label: "40% target", tone: "info" },
          ]}
        />
      </Stack>

      <Grid columns={2} gap={20}>
        <Stack gap={8}>
          <H2>Base roll</H2>
          <Text size="small" tone="secondary">
            Degrees. mjlab stays under 4°. Isaac exceeds 90° after the fall.
          </Text>
          <LineChart
            categories={T}
            series={[
              { name: "mjlab", data: ROLL_MJ, tone: "success" },
              { name: "Isaac Sim", data: ROLL_IS, tone: "danger" },
            ]}
            height={240}
            beginAtZero={false}
          />
        </Stack>
        <Stack gap={8}>
          <H2>Base pitch</H2>
          <Text size="small" tone="secondary">
            Degrees. Isaac pitch runs away from 1.4 s and parks near −80°.
          </Text>
          <LineChart
            categories={T}
            series={[
              { name: "mjlab", data: PITCH_MJ, tone: "success" },
              { name: "Isaac Sim", data: PITCH_IS, tone: "danger" },
            ]}
            height={240}
            beginAtZero={false}
          />
        </Stack>
      </Grid>

      <Stack gap={8}>
        <H2>Outcome and error</H2>
        <Table
          headers={["Metric", "mjlab", "Isaac Sim"]}
          columnAlign={["left", "right", "right"]}
          rowTone={["success", "danger", "success", "danger", "neutral", "neutral", "neutral"]}
          rows={[
            ["Success (reach bottom, stand up, stay upright)", "yes", "no"],
            ["Min pelvis height", "0.276 m (on target)", "0.079 m (on floor)"],
            ["Final pelvis height", "0.686 m", "0.088 m"],
            ["Max |roll| / |pitch|", "3.6° / 1.5°", "101° / 80°"],
            ["XY drift (max)", "0.084 m", "0.632 m"],
            ["Joint-pos RMSE (all 31)", "—", "0.228 rad (13.1°)"],
            ["Action RMSE (after shared step 0)", "—", "1.46"],
          ]}
        />
      </Stack>

      <Grid columns={2} gap={20}>
        <Stack gap={8}>
          <H2>XY drift</H2>
          <Text size="small" tone="secondary">
            Horizontal distance from start (m). Isaac slides as it goes down.
          </Text>
          <LineChart
            categories={T}
            series={[
              { name: "mjlab", data: XY_MJ, tone: "success" },
              { name: "Isaac Sim", data: XY_IS, tone: "danger" },
            ]}
            height={220}
          />
        </Stack>
        <Stack gap={8}>
          <H2>Policy action L2 gap</H2>
          <Text size="small" tone="secondary">
            ||a_mjlab − a_isaac||. Step 0 matches; the closed loop has already
            diverged by 0.1 s.
          </Text>
          <LineChart
            categories={T}
            series={[{ name: "action L2", data: ACT_L2, tone: "warning" }]}
            height={220}
          />
        </Stack>
      </Grid>

      <Stack gap={8}>
        <H2>Knee joints</H2>
        <Text size="small" tone="secondary">
          Position (rad). Both start at the squat default 0.4 rad. Isaac never
          finishes the deep-squat / stand-up cycle.
        </Text>
        <LineChart
          categories={T}
          series={[
            { name: "left knee mjlab", data: KNEE_L_MJ, tone: "success" },
            { name: "left knee Isaac", data: KNEE_L_IS, tone: "danger" },
            { name: "right knee mjlab", data: KNEE_R_MJ, tone: "info" },
            { name: "right knee Isaac", data: KNEE_R_IS, tone: "warning" },
          ]}
          height={260}
        />
      </Stack>

      <Stack gap={8}>
        <H2>Largest joint RMSE</H2>
        <Text size="small" tone="secondary">
          Over the full 6.5 s, including after Isaac has fallen. Wrists and the
          right leg dominate because the fallen pose is unconstrained.
        </Text>
        <Table
          headers={["Joint", "RMSE (deg)"]}
          columnAlign={["left", "right"]}
          rows={[
            ["right_wrist_roll_joint", "24.9"],
            ["right_wrist_pitch_joint", "24.5"],
            ["right_knee_joint", "23.1"],
            ["right_hip_yaw_joint", "21.8"],
            ["right_hip_roll_joint", "21.5"],
            ["left_knee_joint", "21.4"],
            ["left_hip_roll_joint", "18.2"],
            ["left_ankle_pitch_joint", "16.9"],
            ["left_hip_pitch_joint", "16.5"],
            ["right_ankle_pitch_joint", "15.8"],
          ]}
        />
      </Stack>

      <Divider />

      <Stack gap={8}>
        <H2>What was matched, and what still differs</H2>
        <Text>
          The npz, observation layout, command, default pose, and PD gains were
          the same on both sides. Isaac boots
          `20260730_215012-x2_box_v31_flatfoot` only to construct the X2
          articulation, then `q_des = default + action_scale * action` is applied
          through the WBT action scales so the position target is the squat
          target. Armature 0.03 and friction 0.3 (mjlab `x2.xml`). Virtual gantry
          off. WBT box teleported to (20, 20, 1) every step — confirmed in the
          dump. Terminations and observation noise off.
        </Text>
        <Text>
          Remaining plant gap: PhysX with Holosoma’s explicit torque PD and
          full-body URDF colliders (self-collisions on) versus MuJoCo implicit
          position actuators and feet-only geoms. Knee/thigh/torso collision
          meshes could not be disabled at runtime: they live on USD instance
          proxies, and uninstancing them after PhysX is cooked kills the
          backend. Contact sensor already reports multi-kN torso/wrist/knee
          forces at t = 0 while the robot is still standing, which mjlab never
          sees. That is the likely reason the same policy falls in Isaac and
          not in mjlab.
        </Text>
      </Stack>
    </Stack>
  );
}
